// Picks one quote per clock hour, so it changes hourly and differs from one day to the next.
export function currentBibleQuote(date = new Date()) {
  const hourIndex = Math.floor(date.getTime() / 3600000);
  const index = ((hourIndex * 2654435761) % BIBLE_QUOTES.length + BIBLE_QUOTES.length) % BIBLE_QUOTES.length;
  return BIBLE_QUOTES[index];
}
